package org.sleepwell.app;
import android.content.*;import org.json.*;import org.junit.Test;import java.util.*;import java.io.*;import java.nio.file.Files;import static org.junit.Assert.*;
/** Real SQLite/backup and WAV identities; synthetic classifier frames only, no microphone/output. */
public final class SoundInclusionStorageTest {
 @Test public void legacyPrivateCodecMeansAllIncludedAndVersionTwoRejectsMalformedOrEmptySelection()throws Exception{SoundSensitivityStorageTest h=new SoundSensitivityStorageTest();h.fixture((prefs,name)->{SoundSensitivity def=SoundSensitivity.DEFAULT;assertEquals(def,SoundSensitivitySettings.read(prefs).policy);JSONObject v1=new JSONObject(SoundSensitivityJson.encode(def));v1.remove("included");v1.put("version",1);assertEquals(def,SoundSensitivityJson.decode(v1.toString()));for(String category:SoundSensitivity.SELECTABLE){SoundSensitivity chosen=def.include(category,false);SoundSensitivitySettings.of(prefs).save(chosen);assertEquals(chosen,SoundSensitivitySettings.read(prefs).policy);}JSONObject v2=new JSONObject(SoundSensitivityJson.encode(def));List<JSONObject> invalid=new ArrayList<>();for(Object bad:new Object[]{"false",0,JSONObject.NULL}){JSONObject x=new JSONObject(v2.toString());x.getJSONObject("included").put("speech",bad);invalid.add(x);}JSONObject missing=new JSONObject(v2.toString());missing.getJSONObject("included").remove("speech");invalid.add(missing);JSONObject extra=new JSONObject(v2.toString());extra.getJSONObject("included").put("unknown",true);invalid.add(extra);JSONObject empty=new JSONObject(v2.toString());for(String key:SoundSensitivity.SELECTABLE)empty.getJSONObject("included").put(key,false);invalid.add(empty);JSONObject forged=new JSONObject(v1.toString());forged.put("included",v2.getJSONObject("included"));invalid.add(forged);for(JSONObject row:invalid){assertThrows(IllegalArgumentException.class,()->SoundSensitivityJson.decode(row.toString()));assertTrue(prefs.edit().putString(SoundSensitivitySettings.KEY,row.toString()).commit());Map<String,?> before=new HashMap<>(prefs.getAll());assertEquals(def,SoundSensitivitySettings.read(prefs).policy);assertFalse(SoundSensitivitySettings.read(prefs).error.isEmpty());assertEquals(before,prefs.getAll());}});}
 @Test public void filteringNewEstimatesSuppressesAllNewWavsAndLeavesOldEvidenceLabelsAndPortableMetadataUnchanged()throws Exception{SoundSensitivityStorageTest h=new SoundSensitivityStorageTest();h.fixture((prefs,name)->{String db=name+".db",restore=name+"-restore.db";File directory=new File(h.c.getFilesDir(),"clips"),oldWave=new File(directory,name+"-old.wav"),forbidden=new File(directory,name+"-forbidden.wav");assertTrue(directory.isDirectory()||directory.mkdirs());try(Store store=new Store(h.c,db)){long old=store.begin();long oldStart=store.rows("SELECT start FROM sessions WHERE id=?",""+old).get(0).getLong("start");NoiseRecorder.writeWave(oldWave,new byte[64000]);byte[] original=Files.readAllBytes(oldWave.toPath());store.clip(old,oldStart+2000,oldWave.getName(),.7,2000);store.soundEvent(old,oldStart,1950,"snoring",.9,null);store.end(old,false,3000,oldStart+3000);JSONObject oldEvent=store.rows("SELECT * FROM sound_events WHERE session=?",""+old).get(0);RecordEntry record=Records.get(store,old);SoundLabels.save(store,new SoundLabels.Snapshot(oldEvent,record.updated,record.edit.start,record.edit.end),"speech");String evidence=store.rows("SELECT * FROM sound_events WHERE session=?",""+old).get(0).toString();SoundSensitivity selected=SoundSensitivity.DEFAULT.include("snoring",false);SoundSensitivitySettings.of(prefs).save(selected);ClipBudget run=new ClipBudget(SoundSensitivitySettings.read(prefs).policy);long next=store.begin();long start=store.rows("SELECT start FROM sessions WHERE id=?",""+next).get(0).getLong("start");SoundAnalysis.Group groups=new SoundAnalysis.Group((at,n,c,score)->{assertTrue(run.saveEvent());store.soundEvent(next,at,n*975L,c,score,null);if(run.canStart(0)&&run.permitsClips(true))try{NoiseRecorder.writeWave(forbidden,new byte[64000]);fail("Custom selection cannot write any new audio");}catch(IOException error){throw new IllegalStateException(error);}},run.sensitivity);groups.add(start,new SoundAnalysis.Result("snoring",.9));groups.add(start+975,new SoundAnalysis.Result("snoring",.9));groups.add(start+1950,new SoundAnalysis.Result("speech",.85));groups.add(start+2925,new SoundAnalysis.Result("speech",.85));groups.flush();store.end(next,false,4000,start+4000);assertFalse(forbidden.exists());assertEquals(1,store.rows("SELECT * FROM clips").size());assertArrayEquals(original,Files.readAllBytes(oldWave.toPath()));assertEquals(evidence,store.rows("SELECT * FROM sound_events WHERE session=?",""+old).get(0).toString());List<JSONObject> events=store.rows("SELECT * FROM sound_events WHERE session=?",""+next);assertEquals(1,events.size());assertEquals("speech",events.get(0).getString("category"));assertEquals(.85,events.get(0).getDouble("score"),0);assertTrue(events.get(0).isNull("clip"));JSONObject backup=store.backup();Backup.validate(backup);assertFalse(backup.has("soundSensitivity"));try(Store target=new Store(h.c,restore)){Backup.restoreData(target,backup);JSONObject retained=target.rows("SELECT * FROM sound_events WHERE session=?",""+old).get(0);assertEquals("snoring",retained.getString("category"));assertEquals("speech",retained.getString("user_category"));assertEquals(.9,retained.getDouble("score"),0);assertEquals(oldEvent.getString("model"),retained.getString("model"));assertEquals(1,retained.getLong("label_revision"));assertTrue(retained.isNull("clip"));}}finally{assertTrue(!forbidden.exists()||forbidden.delete());assertTrue(!oldWave.exists()||oldWave.delete());assertTrue(h.c.deleteDatabase(db));assertTrue(h.c.deleteDatabase(restore));}});}
 @Test public void unreadableExistingOrUnavailableSettingsNeverRestoreClipOrAnalysisAdmissionUntilExplicitSave()throws Exception{SoundSensitivityStorageTest h=new SoundSensitivityStorageTest();h.fixture((prefs,name)->{SoundSensitivitySettings.Factory previous=SoundSensitivitySettings.factory;try{SoundSensitivitySettings.factory=context->SoundSensitivitySettings.of(prefs);assertTrue(SoundSensitivitySettings.snapshot(h.c).available());assertTrue(new ClipBudget(SoundSensitivitySettings.snapshot(h.c)).permitsClips(true));JSONObject legacy=new JSONObject(SoundSensitivityJson.encode(SoundSensitivity.DEFAULT));legacy.remove("included");legacy.put("version",1);assertTrue(prefs.edit().putString(SoundSensitivitySettings.KEY,legacy.toString()).commit());assertTrue(SoundSensitivitySettings.snapshot(h.c).allIncluded());SoundSensitivitySettings.of(prefs).save(SoundSensitivity.DEFAULT.include("speech",false));assertTrue(prefs.edit().putString(SoundSensitivitySettings.KEY,"{broken").commit());Map<String,?> unchanged=new HashMap<>(prefs.getAll());SoundSensitivity blocked=SoundSensitivitySettings.snapshot(h.c);assertFalse(blocked.available());assertFalse(new ClipBudget(blocked).analysisAllowed());assertFalse(new ClipBudget(blocked).permitsClips(true));assertEquals(unchanged,prefs.getAll());assertFalse(SoundSensitivitySettings.read(prefs).error.isEmpty());assertThrows(IllegalArgumentException.class,()->SoundSensitivityJson.encode(blocked));SoundSensitivitySettings.factory=context->{throw new IllegalStateException("Unavailable private storage fixture");};assertFalse(SoundSensitivitySettings.snapshot(h.c).available());java.util.concurrent.atomic.AtomicBoolean down=new java.util.concurrent.atomic.AtomicBoolean(true);SoundSensitivitySettings.factory=context->{if(down.get())throw new IllegalStateException("Held private store");return SoundSensitivitySettings.of(prefs);};SoundSensitivitySettings.Port editor=SoundSensitivitySettings.editor(h.c);assertThrows(IllegalStateException.class,editor::read);down.set(false);editor.save(SoundSensitivity.DEFAULT);assertEquals(SoundSensitivity.DEFAULT,editor.read().policy);SoundSensitivitySettings.factory=context->SoundSensitivitySettings.of(prefs);SoundSensitivitySettings.of(prefs).save(SoundSensitivity.DEFAULT);assertTrue(SoundSensitivitySettings.snapshot(h.c).available());assertTrue(new ClipBudget(SoundSensitivitySettings.snapshot(h.c)).permitsClips(true));assertFalse(blocked.available());}finally{SoundSensitivitySettings.factory=previous;}});}

}
